import meta from './holidayData/meta.json'
import zoneCountryTable from './holidayData/zones.json'

/**
 * Public holidays, by country, offline. The data is generated by `npm run generate:holidays`
 * (see scripts/generate-holidays.mjs): one small file per country, loaded on first use, so the
 * app never ships the holiday library and never goes to the network.
 *
 * A city has no country of its own — its IANA zone does. `countryOfZone` is that mapping, taken
 * from the tz database's zone.tab, so `Europe/Vaduz` is Liechtenstein, not Switzerland.
 */

export interface CalendarDay {
  year: number
  month: number
  day: number
}

/** `[["MM-DD", name], …]` per year, as generated. */
export type CountryHolidays = Readonly<Record<string, ReadonlyArray<readonly [string, string]>>>

/**
 * How far to trust "no holiday shown":
 *  full    = the data source covers this country's public holidays;
 *  partial = it covers some (see `coverageNote`) — a missing holiday is not proof of none;
 *  none    = the source has nothing for this country;
 *  unknown = the zone belongs to no country (UTC, Etc/*).
 */
export type HolidayCoverage = 'full' | 'partial' | 'none' | 'unknown'

/** First and last year the bundled data covers. Outside it nothing is shown. */
export const HOLIDAY_YEARS: readonly [number, number] = [meta.years[0], meta.years[1]]

export const HOLIDAY_DATA_SOURCE = meta.source

const zoneToCountry = zoneCountryTable as Readonly<Record<string, string>>
const countryNames = meta.countries as Readonly<Record<string, string>>
const noData = new Set<string>(meta.noData)
const partialNotes = meta.partial as Readonly<Record<string, string>>

/** ISO 3166 country code for an IANA zone (or any alias of one); null when it has none. */
export function countryOfZone(iana: string): string | null {
  const direct = zoneToCountry[iana]
  if (direct) return direct
  try {
    // A name this table has not heard of (a newer alias): ask the runtime for its canonical one.
    const canonical = new Intl.DateTimeFormat('en', { timeZone: iana }).resolvedOptions().timeZone
    return zoneToCountry[canonical] ?? null
  } catch {
    return null
  }
}

export function countryName(code: string): string {
  return countryNames[code] ?? code
}

export function holidayCoverage(code: string | null): HolidayCoverage {
  if (code === null) return 'unknown'
  if (noData.has(code)) return 'none'
  return partialNotes[code] ? 'partial' : 'full'
}

/** What is missing for a partially covered country, or null. */
export function coverageNote(code: string | null): string | null {
  return code ? (partialNotes[code] ?? null) : null
}

export interface CoverageGap {
  code: string
  country: string
  /** `partial`: some holidays are missing (see `note`); `none`: the source has none for the country. */
  coverage: 'partial' | 'none'
  note: string | null
}

/**
 * Which of these zones' countries the holiday data does not fully cover, one entry per country,
 * by name. Countries that are fully covered, and zones with no country (UTC), are not listed.
 */
export function coverageGaps(zones: readonly string[]): CoverageGap[] {
  const gaps = new Map<string, CoverageGap>()
  for (const zone of zones) {
    const code = countryOfZone(zone)
    const coverage = holidayCoverage(code)
    if (!code || gaps.has(code) || (coverage !== 'partial' && coverage !== 'none')) continue
    gaps.set(code, { code, country: countryName(code), coverage, note: coverageNote(code) })
  }
  return [...gaps.values()].sort((a, b) => a.country.localeCompare(b.country))
}

// --- Loading -----------------------------------------------------------------------------------

type HolidayLoader = (code: string) => Promise<CountryHolidays | null>

const loaded = new Map<string, CountryHolidays | null>()
const loading = new Map<string, Promise<CountryHolidays | null>>()

/** One country's file, as its own chunk: nothing is fetched until a city in that country is added. */
const fromBundle: HolidayLoader = (code) =>
  import(`./holidayData/countries/${code}.json`).then((module: { default: CountryHolidays }) => module.default ?? null)

let loader: HolidayLoader = fromBundle

/**
 * Swap where country files come from, and forget what was loaded. A seam for tests: the shared test
 * setup passes `null` (no holidays anywhere), so no test depends on today's date being an ordinary
 * day somewhere; tests of the holiday data itself call it with no argument to get the real files back.
 */
export function setHolidayLoader(next?: HolidayLoader | null): void {
  loader = next === undefined ? fromBundle : (next ?? (() => Promise.resolve(null)))
  loaded.clear()
  loading.clear()
}

/** True for a country the data source covers, at least in part. */
export function hasHolidayData(code: string | null): boolean {
  if (code === null || !Object.hasOwn(countryNames, code)) return false
  const coverage = holidayCoverage(code)
  return coverage === 'full' || coverage === 'partial'
}

/**
 * Load one country's holidays (once; later calls reuse it). Resolves to null for a country the
 * data does not cover, and for anything that is not a two-letter code.
 */
export function loadCountryHolidays(code: string): Promise<CountryHolidays | null> {
  if (!/^[A-Z]{2}$/.test(code) || !hasHolidayData(code)) return Promise.resolve(null)
  const cached = loading.get(code)
  if (cached) return cached
  const request = loader(code).then(
    (table) => {
      loaded.set(code, table)
      return table
    },
    () => {
      // A chunk that failed to load (offline, flaky network) is not "no holidays": forget the
      // attempt so the next request tries again, and show nothing meanwhile.
      loading.delete(code)
      return null
    }
  )
  loading.set(code, request)
  return request
}

/** What has been loaded so far: undefined = not yet, null = no data for this country. */
export function peekCountryHolidays(code: string): CountryHolidays | null | undefined {
  return loaded.get(code)
}

// --- Lookup ------------------------------------------------------------------------------------

const two = (n: number): string => String(n).padStart(2, '0')

/** Names of the public holidays on `day` in this table; empty when none or not loaded. */
export function holidayNames(table: CountryHolidays | null | undefined, day: CalendarDay): string[] {
  const rows = table?.[String(day.year)]
  if (!rows) return []
  const mmdd = `${two(day.month)}-${two(day.day)}`
  return rows.filter(([date]) => date === mmdd).map(([, name]) => name)
}

/** A calendar day and every public holiday on it. */
export interface HolidayDay extends CalendarDay {
  names: string[]
}

/** Whole calendar days from `a` to `b` (negative when `b` is earlier). No clock or zone involved. */
export function daysBetween(a: CalendarDay, b: CalendarDay): number {
  const utc = (d: CalendarDay): number => Date.UTC(d.year, d.month - 1, d.day)
  return Math.round((utc(b) - utc(a)) / 86_400_000)
}

/**
 * The next `count` days that have a public holiday, starting on `from` itself, each with all of
 * its holidays (two holidays on one day are one entry). Reads only what the table covers, so near
 * the end of the generated years it can return fewer than `count`, or none.
 */
export function upcomingHolidays(
  table: CountryHolidays | null | undefined,
  from: CalendarDay,
  count = 5
): HolidayDay[] {
  if (!table || count < 1) return []
  const years = Object.keys(table).map(Number).filter(Number.isInteger)
  const last = Math.max(...years)
  const found: HolidayDay[] = []
  for (let year = from.year; year <= last && found.length < count; year++) {
    const rows = table[String(year)]
    if (!rows) continue
    const earliest = year === from.year ? `${two(from.month)}-${two(from.day)}` : ''
    for (const [mmdd, name] of [...rows].sort((a, b) => a[0].localeCompare(b[0]))) {
      if (mmdd < earliest) continue
      const previous = found[found.length - 1]
      const month = Number(mmdd.slice(0, 2))
      const day = Number(mmdd.slice(3))
      if (previous && previous.year === year && previous.month === month && previous.day === day) {
        previous.names.push(name)
      } else if (found.length < count) {
        found.push({ year, month, day, names: [name] })
      } else {
        break // the next day's holidays are not wanted; this day's are all collected
      }
    }
  }
  return found
}

/** A function from (zone, calendar day in that zone) to the holidays there. */
export type HolidayLookup = (iana: string, day: CalendarDay) => string[]

/** Synchronous lookup over whatever has been loaded: empty until a country's data arrives. */
export const lookupHolidays: HolidayLookup = (iana, day) => {
  const code = countryOfZone(iana)
  return code ? holidayNames(peekCountryHolidays(code), day) : []
}
